  const packet = buildPacket(before.data, terms.data, before.sha, new Date().toISOString(), after ? {
    after: after.data, afterSha: after.sha, postBefore: pb?.data, postAfter: pa?.data,
    postBeforeSha: pb?.sha, postAfterSha: pa?.sha,
