// MIT. Export payment-specific fields from an actual SF81 call, never Response body or signing keys.
const id = v => typeof v === 'string' && /^[A-Za-z0-9._:-]{1,160}$/.test(v);
const approvedFields = ['request_id','actor','service','network','asset','scheme','max_amount',
  'resource','pay_to','max_timeout_seconds','method','body_present','body_bytes',
  'body_sha256','accepted_terms_sha256'];
export function sf81ReconciliationRecord(result) {
  if (!result || !id(result.intentId) || result.attempts !== 2 ||
      !result.requirement || !result.receipt || !result.operatorReservation ||
      !['REPORTED_SUCCESS', 'PENDING'].includes(result.settlement)) {
    throw new TypeError('original paid SF81 result with receipt and reservation required');
  }
  const { requirement: q, receipt: r, operatorReservation: p } = result;
  if (p.schema !== 'stellar-forge.sf62.result.v1' ||
      p.outcome !== 'FRESH_RESERVATION_APPROVED' || p.request_id !== result.intentId ||
      p.network !== q.network || p.asset !== q.asset ||
      p.reserved_atomic_units !== q.amount || r.network !== q.network) {
    throw new TypeError('original SF81 operator reservation/receipt mismatch');
  }
  return {
    intentId: result.intentId,
    requirement: { scheme: q.scheme, network: q.network, asset: q.asset,
      payTo: q.payTo, amount: q.amount },
    receipt: { network: r.network, transaction: r.transaction, payer: r.payer,
      success: r.success, ...(r.amount === undefined ? {} : { amount: r.amount }),
      ...(r.errorReason === undefined ? {} : { errorReason: r.errorReason }) },
    operatorReservation: { schema: p.schema, outcome: p.outcome,
      request_id: p.request_id, network: p.network, asset: p.asset,
      ...(p.request_sha256 === undefined ? {} : {request_sha256:p.request_sha256}),
      ...(p.approved_request === undefined ? {} :
        {approved_request:Object.fromEntries(approvedFields.map(key=>[key,p.approved_request[key]]))}),
      reserved_atomic_units: p.reserved_atomic_units },
  };
}

// MIT. Atomic private records for the original SF82 checkout and its recovery.
import {constants} from 'node:fs';
import {open,lstat,link,unlink,readdir} from 'node:fs/promises';
import {dirname,join,isAbsolute} from 'node:path';
import {createHash,randomUUID} from 'node:crypto';

export const CHECKOUT_RECORD_LIMIT=262144;
const tag=/^[A-Za-z0-9._:-]{1,128}$/;
const fail=(ok,code)=>{if(!ok)throw new TypeError(code);};
const digest=raw=>createHash('sha256').update(raw).digest('hex');
export function checkoutPaths(outputDir,intentId) {
 fail(typeof outputDir==='string'&&isAbsolute(outputDir)&&!outputDir.includes('\0'),'ABSOLUTE_PRIVATE_EVIDENCE_DIRECTORY_REQUIRED');
 fail(typeof intentId==='string'&&tag.test(intentId),'TRUSTED_BUYER_AND_STABLE_INTENT_REQUIRED');
 const base=join(outputDir,digest(intentId));
 return {evidencePath:base+'.json',checkpointPath:base+'.checkpoint.json',bodyPath:base+'.body-checkpoint.json'};
}
async function privateDirectory(directory) {
 const info=await lstat(directory);
 fail(info.isDirectory()&&!info.isSymbolicLink(),'EVIDENCE_PATH_NOT_DIRECTORY');
}
export async function readCheckoutRecord(file,{optional=false}={}) {
 await privateDirectory(dirname(file));
 let handle;
 try {handle=await open(file,constants.O_RDONLY|(constants.O_NOFOLLOW??0));}
 catch(error){if(optional&&error.code==='ENOENT')return null;throw error;}
 try {
  const info=await handle.stat();
  fail(info.isFile()&&info.size<=CHECKOUT_RECORD_LIMIT,'CHECKOUT_RECORD_INVALID_OR_TOO_LARGE');
  const bytes=await handle.readFile();
  fail(bytes.length<=CHECKOUT_RECORD_LIMIT,'CHECKOUT_RECORD_INVALID_OR_TOO_LARGE');
  const value=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
  return {value,bytes:bytes.length,sha256:digest(bytes),path:file};
 } finally {await handle.close();}
}
export async function createCheckoutRecord(file,value) {
 await privateDirectory(dirname(file));
 const bytes=Buffer.from(JSON.stringify(value,null,2)+'\n');
 fail(bytes.length<=CHECKOUT_RECORD_LIMIT,'CHECKOUT_RECORD_INVALID_OR_TOO_LARGE');
 const temporary=join(dirname(file),'.checkout-'+randomUUID()+'.tmp');
 const handle=await open(temporary,constants.O_WRONLY|constants.O_CREAT|constants.O_EXCL|(constants.O_NOFOLLOW??0),0o600);
 try {
  try {await handle.writeFile(bytes);await handle.sync();} finally {await handle.close();}
  // Link publishes complete bytes with create-only semantics. A failed write
  // leaves no empty terminal record, and a concurrent winner is never replaced.
  await link(temporary,file);
  const directory=await open(dirname(file),'r');
  try {await directory.sync();} finally {await directory.close();}
  return {value,bytes:bytes.length,sha256:digest(bytes),path:file};
 } finally {
  await unlink(temporary).catch(error=>{if(error.code!=='ENOENT')throw error;});
 }
}


/** Complete a publication interrupted between hard-link publication and removal
 * of this writer's temporary name. The published bytes are never replaced. */
export async function finishCheckoutRecordPublication(file) {
 await privateDirectory(dirname(file));
 let target;
 try {target=await lstat(file);}catch(error){if(error.code==='ENOENT')return;throw error;}
 fail(target.isFile()&&!target.isSymbolicLink(),'CHECKOUT_RECORD_INVALID_OR_TOO_LARGE');
 if(target.nlink<=1)return;
 let removed=false;
 for(const name of await readdir(dirname(file))) {
  if(!/^\.checkout-[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}\.tmp$/.test(name))continue;
  const candidate=join(dirname(file),name);
  let info;
  try {info=await lstat(candidate);}catch(error){if(error.code==='ENOENT')continue;throw error;}
  if(!info.isFile()||info.isSymbolicLink()||info.dev!==target.dev||info.ino!==target.ino)continue;
  const current=await lstat(file);
  fail(current.dev===target.dev&&current.ino===target.ino,'CHECKOUT_PUBLISHED_FILE_CHANGED');
  try {await unlink(candidate);removed=true;}catch(error){if(error.code!=='ENOENT')throw error;}
 }
 if(removed) {
  const parent=await open(dirname(file),'r');
  try {await parent.sync();}finally{await parent.close();}
 }
}

// MIT — SCF SF82: one original approved buyer attempt to independently observed evidence.
// Trusted operator-host adapter; not an agent-facing signer, new payment controller or ledger.
import { createHash } from 'node:crypto';
import { stat } from 'node:fs/promises';
import { isAbsolute } from 'node:path';
import { checkStellarTransaction, createOfficialEventDecoder } from '../sf43-agent-commerce/verify.mjs';
import { captureBuyerResult, captureBuyerError, aggregateOutcomes } from '../sf52-buyer-outcomes/outcomes.mjs';
import { sf81ReconciliationRecord } from '../sf82-chain-transfer-reconcile/record.mjs';
import {checkoutPaths,readCheckoutRecord,createCheckoutRecord,finishCheckoutRecordPublication} from './checkpoint.mjs';

const tag = /^[A-Za-z0-9._:-]{1,128}$/; // Original SF52 observation identity limit.
const payer = /^[GC][A-Z2-7]{55}$/;
const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v);

async function bodyEvidence(response, maxBytes, timeoutMs) {
  if (!response || typeof response.clone !== 'function' || !Number.isInteger(response.status) ||
      response.status < 200 || response.status >= 300) return { status: 'NO_SUCCESSFUL_HTTP_BODY' };
  let clone;
  try { clone = response.clone(); } catch { return { status: 'BODY_NOT_CLONEABLE' }; }
  if (!clone.body || typeof clone.body.getReader !== 'function') return { status: 'NO_BODY_STREAM' };
  const hash = createHash('sha256');
  const reader = clone.body.getReader();
  let size = 0, timer;
  const deadline = new Promise(resolve => {
    timer = setTimeout(() => resolve({ timedOut: true }), timeoutMs);
  });
  try {
    for (;;) {
      // The race also handles late read rejection after a timeout; no ignored
      // read can become an unhandled rejection after evidence is returned.
      const next = await Promise.race([reader.read(), deadline]);
      if (next.timedOut) return { status: 'BODY_CAPTURE_TIMED_OUT', timeoutMs };
      const { done, value } = next;
      if (done) return { status: 'HTTP_BODY_OBSERVED', httpStatus: response.status,
        bodySha256: hash.digest('hex'), bodyBytes: size };
      if (!(value instanceof Uint8Array)) return { status: 'INVALID_BODY_CHUNK' };
      size += value.byteLength;
      if (size > maxBytes) return { status: 'BODY_OVER_LIMIT', limitBytes: maxBytes };
      hash.update(value);
    }
  } catch { return { status: 'BODY_READ_FAILED' }; }
  finally {
    clearTimeout(timer);
    try { void reader.cancel().catch(() => {}); } catch {}
    try { reader.releaseLock(); } catch {}
  }
}

// SF81's reservation is already durable in its original SF36 ledger. Export ONLY
// fixed non-secret fields; never persist operator policy, TTY transcript or wallet.
function reservationMetadata(raw) {
  if (!isObject(raw)) return null;
  const r = {};
  for (const [from, to] of [['outcome', 'outcome'], ['request_id','requestId'],
    ['request_sha256','requestSha256'], ['asset','asset'],
    ['network','network'], ['reserved_atomic_units','reservedAtomicUnits']]) {
    const v = raw[from];
    if (typeof v === 'string' && v.length <= 160) r[to] = v;
  }
  return Object.keys(r).length ? r : null;
}

/**
 * Invoke original SF81 exactly once; feed original SF31 result to SF52, and a
 * compatible network-bound receipt to ORIGINAL SF43 RPC/SEP-41 verification.
 *
 * buyer: the trusted host's existing OperatorApprovedBuyer (no new approval).
 * call:  exact existing SF81 call options, including trusted signer and intentId.
 * outputDir: pre-existing private absolute directory, chosen by the operator.
 * trustedPayer: actual payer returned/bound by the trusted signer, never seller data.
 * decodeContractEvent: original createOfficialEventDecoder() or trusted SDK decoder.
 * captureBody: bounded opt-in body-hash from cloned successful HTTP Response.
 * rpcEndpoint/rpcFetch: SF43's own restricted endpoint and HTTP implementation;
 *                     loopback override is intended ONLY for focused local tests.
 * Returns {result,error,evidencePath,report}. Never blindly retries a signed call.
 */
export async function executeWithEvidence({buyer, call, outputDir, trustedPayer,
  decodeContractEvent, rpcEndpoint, rpcFetch, captureBody = false,
  maxBodyBytes = 1_048_576, bodyCaptureTimeoutMs = 15000,
  observedAt = new Date().toISOString()} = {}) {
  if (!isObject(buyer) || typeof buyer.call !== 'function' || !isObject(call) ||
      typeof call.intentId !== 'string' || !tag.test(call.intentId))
    throw new TypeError('TRUSTED_BUYER_AND_STABLE_INTENT_REQUIRED');
  if (typeof outputDir !== 'string' || !isAbsolute(outputDir) || outputDir.includes('\0'))
    throw new TypeError('ABSOLUTE_PRIVATE_EVIDENCE_DIRECTORY_REQUIRED');
  if (trustedPayer !== undefined && (typeof trustedPayer !== 'string' || !payer.test(trustedPayer)))
    throw new TypeError('TRUSTED_STELLAR_PAYER_INVALID');
  if (decodeContractEvent !== undefined && typeof decodeContractEvent !== 'function')
    throw new TypeError('DECODER_MUST_BE_TRUSTED_FUNCTION');
  if (rpcFetch !== undefined && typeof rpcFetch !== 'function') throw new TypeError('RPC_FETCH_INVALID');
  if (typeof captureBody !== 'boolean' || !Number.isSafeInteger(maxBodyBytes) ||
      maxBodyBytes < 1 || maxBodyBytes > 8_388_608)
    throw new TypeError('BODY_CAPTURE_LIMIT_INVALID');
  if (!Number.isSafeInteger(bodyCaptureTimeoutMs) || bodyCaptureTimeoutMs < 1 || bodyCaptureTimeoutMs > 60000)
    throw new TypeError('BODY_CAPTURE_TIMEOUT_INVALID');
  // Validate original SF52's exact timestamp contract before a buyer can sign.
  // This preflight observation is never persisted as an actual buyer attempt.
  captureBuyerError({intentId:call.intentId,error:{paymentSent:false,code:'EVIDENCE_PREFLIGHT'},observedAt});
  const directory = await stat(outputDir);
  if (!directory.isDirectory()) throw new TypeError('EVIDENCE_PATH_NOT_DIRECTORY');
  const {evidencePath,checkpointPath,bodyPath}=checkoutPaths(outputDir,call.intentId);
  // Fail before invoking a signer when this exact intent already has a terminal
  // report. Cross-process paid-attempt uniqueness remains SF36's original job.
  try {
    await stat(evidencePath);
    throw new Error('TERMINAL_EVIDENCE_ALREADY_EXISTS_USE_EXISTING_SF36_LEDGER');
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }

  // A returned original buyer result is a durable continuation even if its
  // later RPC observation or terminal file was interrupted.
  if (await readCheckoutRecord(checkpointPath,{optional:true}))
    throw new Error('CHECKOUT_CHECKPOINT_EXISTS_USE_RECOVERY');

  let result = null, error = null;
  try { result = await buyer.call(call); }
  catch (e) { error = e; }
  // Retain the original approved record while it is still available. The
  // smaller SF52 observation/reservation summary cannot reconstruct this later.
  let reconciliation = {status:'UNAVAILABLE', reason:'NO_ELIGIBLE_ORIGINAL_SF81_RESULT'};
  if (!error) {
    try { reconciliation = {status:'AVAILABLE', record:sf81ReconciliationRecord(result)}; }
    catch { /* Free, unsupported or incomplete outcomes retain no invented record. */ }
  }
  // The error adapter conservatively marks errors with UNKNOWN paymentSent as
  // potentially signed, not an unapproved, safely repeatable operation.
  const observedError = error && typeof error.paymentSent !== 'boolean' ?
    { paymentSent: true, code: 'UNKNOWN_EXECUTION_PHASE' } : error;
  const base = error ? captureBuyerError({intentId:call.intentId,error:observedError,observedAt}) :
    captureBuyerResult(result,{observedAt});
  const checkpoint=await createCheckoutRecord(checkpointPath,{
    schema:'scf82.checkout-checkpoint.v1',intentId:call.intentId,observedAt,
    trustedPayer:trustedPayer??null,observation:base,reconciliation,
    operatorReservation:reservationMetadata(result?.operatorReservation??error?.operatorReservation),
    captureBody,maxBodyBytes,bodyCaptureTimeoutMs,
  });
  let chain = null, delivery = null;
  let bodyCapture = {status:captureBody ? 'NO_SUCCESSFUL_PAID_BODY' : 'NOT_REQUESTED'};
  if (!error) {
    if (captureBody && base.buyer.requirement) {
      const candidate = await bodyEvidence(result.response,maxBodyBytes,bodyCaptureTimeoutMs);
      bodyCapture = candidate;
      if (candidate.status === 'HTTP_BODY_OBSERVED') {
        delivery = {status:candidate.status,httpStatus:candidate.httpStatus,
          bodySha256:candidate.bodySha256};
      }
    }
  }
  // Retain the completed body-hash observation before the independent RPC work.
  await createCheckoutRecord(bodyPath,{schema:'scf82.checkout-body-checkpoint.v1',
    intentId:call.intentId,checkpointSha256:checkpoint.sha256,bodyCapture});
  if (!error) chain=await observeCheckoutChain(base,{trustedPayer,decodeContractEvent,rpcEndpoint,rpcFetch});

  const observation = {...base, ...(chain ? {chain} : {}), ...(delivery ? {delivery} : {})};
  const report = aggregateOutcomes([observation]);
  const envelope = {
    schema:'scf82.checkout-evidence.v1', intentId:call.intentId, observedAt,
    operatorReservation:reservationMetadata(result?.operatorReservation ?? error?.operatorReservation),
    observation, report, bodyCapture, reconciliation,
    sourceCheckpoint:{path:checkpointPath,sha256:checkpoint.sha256},
    notes:'Original SF43 observes the approved network, transaction and exact SEP-41 transfer. HTTP delivery and original SF36 accounting are recorded separately.',
  };
  await createCheckoutRecord(evidencePath,envelope);
  return { result, error, evidencePath, report };
}

async function observeCheckoutChain(base,{trustedPayer,decodeContractEvent,rpcEndpoint,rpcFetch}={}) {
  const terms=base.buyer.requirement,receipt=base.buyer.receipt;
  if (!(trustedPayer&&['stellar:testnet','stellar:pubnet'].includes(terms?.network)&&
      receipt?.success===true&&receipt.network===terms.network&&/^[0-9a-f]{64}$/.test(receipt.transaction||''))) return null;
  let decoder=decodeContractEvent;
  if (!decoder) {
    try {decoder=await createOfficialEventDecoder();}
    catch {decoder=undefined;}
  }
  return checkStellarTransaction({
    receipt:{...receipt,payer:trustedPayer},
    expected:{network:terms.network,asset:terms.asset,payTo:terms.payTo,amount:terms.amount,payer:trustedPayer},
    ...(decoder?{decodeContractEvent:decoder}:{}),
    ...(rpcEndpoint!==undefined?{rpcEndpoint}:{}),
    ...(rpcFetch!==undefined?{fetchImpl:rpcFetch}:{}),
  });
}

function terminalRecord(record,intentId) {
  const value=record?.value;
  if (!isObject(value)||value.schema!=='scf82.checkout-evidence.v1'||value.intentId!==intentId||
      value.observation?.intentId!==intentId) throw new TypeError('CHECKOUT_TERMINAL_RECORD_INVALID');
  aggregateOutcomes([value.observation]);
  return {evidencePath:record.path,report:value.report,checkpointPath:value.sourceCheckpoint?.path??null,
    recovered:false,evidenceSha256:record.sha256};
}

/** Finish observation of a saved original buyer result. This API never invokes
 * a buyer, signer, approval, reservation or merchant request. */
export async function recoverCheckoutEvidence({outputDir,intentId,trustedPayer,
  decodeContractEvent,rpcEndpoint,rpcFetch}={}) {
  const {evidencePath,checkpointPath,bodyPath}=checkoutPaths(outputDir,intentId);
  if (trustedPayer!==undefined&&(typeof trustedPayer!=='string'||!payer.test(trustedPayer)))
    throw new TypeError('TRUSTED_STELLAR_PAYER_INVALID');
  if (decodeContractEvent!==undefined&&typeof decodeContractEvent!=='function')
    throw new TypeError('DECODER_MUST_BE_TRUSTED_FUNCTION');
  if (rpcFetch!==undefined&&typeof rpcFetch!=='function')throw new TypeError('RPC_FETCH_INVALID');
  for(const path of [checkpointPath,bodyPath,evidencePath])await finishCheckoutRecordPublication(path);
  const terminal=await readCheckoutRecord(evidencePath,{optional:true});
  if (terminal)return terminalRecord(terminal,intentId);
  const checkpoint=await readCheckoutRecord(checkpointPath),saved=checkpoint.value;
  if (!isObject(saved)||saved.schema!=='scf82.checkout-checkpoint.v1'||saved.intentId!==intentId||
      saved.observation?.intentId!==intentId||saved.observation?.observedAt!==saved.observedAt||
      typeof saved.captureBody!=='boolean'||!isObject(saved.reconciliation)||
      !['AVAILABLE','UNAVAILABLE'].includes(saved.reconciliation.status)||
      (saved.trustedPayer??null)!==(trustedPayer??null))
    throw new TypeError('CHECKOUT_CHECKPOINT_BINDING_MISMATCH');
  aggregateOutcomes([saved.observation]);
  if (saved.reconciliation.status==='AVAILABLE'&&
      (saved.reconciliation.record?.intentId!==intentId||
       saved.reconciliation.record?.operatorReservation?.request_id!==intentId))
    throw new TypeError('CHECKOUT_CHECKPOINT_BINDING_MISMATCH');
  const bodyRecord=await readCheckoutRecord(bodyPath,{optional:true});
  if (bodyRecord&&(bodyRecord.value?.schema!=='scf82.checkout-body-checkpoint.v1'||
      bodyRecord.value?.intentId!==intentId||bodyRecord.value?.checkpointSha256!==checkpoint.sha256||
      !isObject(bodyRecord.value?.bodyCapture)))
    throw new TypeError('CHECKOUT_BODY_CHECKPOINT_BINDING_MISMATCH');
  const bodyCapture=bodyRecord?.value.bodyCapture??{status:saved.captureBody?'CAPTURE_INTERRUPTED':'NOT_REQUESTED'};
  let delivery=null;
  if (bodyCapture.status==='HTTP_BODY_OBSERVED') {
    if (!Number.isSafeInteger(bodyCapture.httpStatus)||bodyCapture.httpStatus<200||bodyCapture.httpStatus>=300||
        !/^[0-9a-f]{64}$/.test(bodyCapture.bodySha256??'')||!Number.isSafeInteger(bodyCapture.bodyBytes)||
        bodyCapture.bodyBytes<0||bodyCapture.bodyBytes>saved.maxBodyBytes)
      throw new TypeError('CHECKOUT_BODY_CHECKPOINT_INVALID');
    delivery={status:bodyCapture.status,httpStatus:bodyCapture.httpStatus,bodySha256:bodyCapture.bodySha256};
  }
